-- 0017. 도면 마크업 스탬프(도장/표) 관리
--
-- 미리보기 툴바에서 도면에 찍을 수 있는 스탬프(도장, 표 등)를 DB 로 관리한다.
-- 운영자가 스탬프 관리 화면(/stamps)에서 등록·수정·삭제하고,
-- 미리보기 툴바에서 활성화된 스탬프 목록을 조회해 도면에 찍을 수 있다.

CREATE TABLE stamps (
  id          bigserial   PRIMARY KEY,
  name        text        NOT NULL CHECK (btrim(name) <> ''),
  category    text        NOT NULL DEFAULT '도장',
  image_url   text        NOT NULL,
  width       integer     NOT NULL DEFAULT 300 CHECK (width > 0),
  height      integer     NOT NULL DEFAULT 150 CHECK (height > 0),
  description text,
  is_enabled  boolean     NOT NULL DEFAULT true,
  sort_order  integer     NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  created_by  bigint      REFERENCES users(id) ON DELETE SET NULL,
  updated_by  bigint      REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX ix_stamps_sort ON stamps (sort_order, id);

COMMENT ON TABLE stamps IS '도면 미리보기 마크업용 스탬프(도장·표) 목록';
COMMENT ON COLUMN stamps.category IS '분류 (도장, 표, 서명, 기타)';
COMMENT ON COLUMN stamps.image_url IS '스탬프 이미지 데이터 URL 또는 주소';
COMMENT ON COLUMN stamps.width IS '스탬프 기준 가로 픽셀';
COMMENT ON COLUMN stamps.height IS '스탬프 기준 세로 픽셀';

-- 스탬프 관리 화면 메뉴 등록
INSERT INTO menus (path, permission_key, label, sort_order, is_enabled, is_fixed)
VALUES ('/stamps', 'screen.users.access', '스탬프 관리', 12, true, false);

